public class Main {
    public static void main(String[] args) {
        Hewan h = new Anjing();
        if (h instanceof Anjing) {
            Anjing a = (Anjing) h;
            a.jaga();
        }
    }
}

class Hewan {
    void suara() {
        System.out.println("Hewan bersuara");
    }
}

class Anjing extends Hewan {
    void jaga() {
        System.out.println("Menjaga rumah");
    }
}

